3834	/// D1 revision 5a.3's verification pass on a solved verification state: the
3835	/// shared verification data (built or reused) and the case's own pass, both
3836	/// charged to the verification attempt, the case budget and the meter (the
3837	/// shared data once against the invocation).
3838	fn verify_precision(
3839	    state: &PrecisionState,
3840	    prep: &Arc<CasePrep>,
3841	    group: &Arc<GroupPrep>,
3842	    cache: &mut GroupCache,
3843	    budget: &mut CaseBudget,
3844	    meter: &mut InvocationMeter,
3845	    record: &mut AttemptRecord,
3846	) -> Result<BoundVerification, AttemptStop> {
3847	    let case_room = budget.limit.saturating_sub(budget.used);
3848	    let invocation_room = meter.room();
3849	    let guard = StageGuard {
3850	        base: 0,
3851	        case_room,
3852	        invocation_room,
3853	    };
3854	    macro_rules! run {
3855	        ($slot:expr, $vslot:expr, $L:literal, $R:literal, $W:literal, $solved:expr, $variant:ident) => {{
3856	            let shared = match $slot {
3857	                Some(Ok(shared)) => shared.clone(),
3858	                _ => unreachable!("a solved state's shared stages are cached"),
3859	            };
3860	            let (vs, vs_total, built, vs_stages, vs_refusals) =
3861	                obtain_verify::<$L, $R, $W>($vslot, &shared, &prep.source, group, guard);
3862	            record.verification_shared_work = vs_total;
3863	            record.verification_shared_built_here = built;
3864	            record.shared_stages.add(&vs_stages);
3865	            let invocation_spent = if built { vs_total } else { 0 };
3866	            budget.used = budget.used.saturating_add(vs_total);
3867	            meter.charge(invocation_spent);
3868	            // RV23-1: a stopped shared build's Uc_c refusals reach the record
3869	            // before its stop propagates.
3870	            if vs.is_err() {
3871	                record.bound_refusals = vs_refusals;
3872	            }
3873	            let vs = vs?;
3874	            // Amendment A2: the shared build's Uc_c refusals, per block.
3875	            record.bound_refusals = block_refusals(&vs.uc, &[]);
3876	            if vs_total > case_room {
3877	                return Err(AttemptStop::Budget(BudgetScope::Case));
3878	            }
3879	            let own_guard = StageGuard {
3880	                base: 0,
3881	                case_room: case_room - vs_total,
3882	                invocation_room: invocation_room.saturating_sub(invocation_spent),
3883	            };
3884	            let spent = verify_state::<$L, $R, $W>(&shared, &vs, prep, group, $solved, own_guard);
3885	            record.work.merge(&spent.work);
