3887	            record.stages.add(&spent.stages);
3888	            record.verification_work = spent.total;
3889	            record.bound_refusals.extend(spent.refusals.iter().copied());
3890	            budget.used = budget.used.saturating_add(spent.total);
3891	            meter.charge(spent.total);
3892	            let report_state = VerificationState::$variant(Arc::new(spent.result?));
3893	            record.verification = Some(report_state.summary()?);
