4342	pub fn solve_cases(
4343	    sources: &[PrimitiveSource],
4344	    case_limit: CaseLimit,
4345	    meter: &mut InvocationMeter,
4346	) -> Vec<CaseOutcome> {
4347	    let mut groups: Vec<(
4348	        Vec<u8>,
4349	        Result<Arc<GroupPrep>, (Refusal, Vec<BodyGeometry>)>,
4350	        GroupCache,
4351	    )> = Vec::new();
4352	    let mut out = Vec::with_capacity(sources.len());
4353	    for source in sources {
4354	        if meter.exhausted() {
4355	            out.push(CaseOutcome::Unresolved {
4356	                reason: UnresolvedReason::Budget(BudgetScope::Invocation),
4357	                attempts: Vec::new(),
4358	                geometry: Vec::new(),
4359	            });
4360	            continue;
4361	        }
4362	        let identity = source.stiffness_encoding();
4363	        let index = match groups.iter().position(|g| g.0 == identity) {
4364	            Some(k) => k,
4365	            None => {
4366	                groups.push((
4367	                    identity,
4368	                    prepare_group(source).map(Arc::new),
4369	                    GroupCache::default(),
4370	                ));
4371	                groups.len() - 1
4372	            }
4373	        };
4374	        let (_, group, cache) = &mut groups[index];
4375	        let group = match group {
4376	            Ok(g) => g.clone(),
4377	            Err((refusal, geometry)) => {
4378	                out.push(CaseOutcome::Refused {
4379	                    refusal: refusal.clone(),
4380	                    geometry: geometry.clone(),
4381	                });
4382	                continue;
4383	            }
4384	        };
4385	        let prep = match CasePrep::new(source.clone()) {
4386	            Ok(p) => Arc::new(p),
4387	            Err(e) => {
4388	                out.push(CaseOutcome::Refused {
4389	                    refusal: Refusal::LedgerUnavailable(e),
4390	                    geometry: group.geometry.clone(),
4391	                });
4392	                continue;
4393	            }
4394	        };
4395	        out.push(run_schedule(prep, group, cache, case_limit, meter));
4396	    }
